package com.shortlinkx.analytics;
import com.shortlinkx.entity.ClickEvent;import com.shortlinkx.repository.*;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.stereotype.Service;
@Service public class ClickEventConsumer{private final ClickEventRepository clicks;private final ShortUrlRepository urls;public ClickEventConsumer(ClickEventRepository clicks,ShortUrlRepository urls){this.clicks=clicks;this.urls=urls;}@KafkaListener(topics="${shortlinkx.analytics-topic}",groupId="shortlinkx-analytics")public void consume(ClickEventPayload e){clicks.save(new ClickEvent(e.shortCode(),e.ipAddress(),e.userAgent(),e.referrer(),e.device(),e.browser(),e.operatingSystem()));urls.findByShortCode(e.shortCode()).ifPresent(u->{u.incrementClicks();urls.save(u);});}}
